    long_desc: List[str] = field(default_factory=list)
    notation: Optional[str] = None
    notations: List[str] = field(default_factory=list)
    required: bool = False
    multiple: bool = False
    multiple_occurs: bool = False
    multiple_values: bool = False
    delimiter: Optional[str] = None
    terminated: bool = False
    assigned: bool = False
    prefixed: bool = False
    default: Optional[str] = None
    default_fn: Optional[str] = None
    choice: Optional[List[str]] = None
    choice_fn: Optional[str] = None
    skip_check: bool = False
    env: Optional[str] = None
    num_args: Tuple[int, Optional[int]] = (1,1)
    raw_display: str = ""
    inherited: bool = False

@dataclass
class EnvDef:
    id: str
    describe: str = ""
    required: bool = False
    default: Optional[str] = None
    default_fn: Optional[str] = None
    choice: Optional[List[str]] = None
    choice_fn: Optional[str] = None

@dataclass
class Node:
    name: str
    fn: Optional[str] = None
    describe: str = ""
    long_desc: List[str] = field(default_factory=list)
    aliases: List[str] = field(default_factory=list)
    options: List[Param] = field(default_factory=list)
    args: List[Param] = field(default_factory=list)
    envs: List[EnvDef] = field(default_factory=list)
    children: Dict[str,'Node'] = field(default_factory=dict)
    child_aliases: Dict[str,str] = field(default_factory=dict)
    meta: Dict[str, Any] = field(default_factory=dict)
    parent: Optional['Node'] = None


def script_name(path: str) -> str:
    base = os.path.basename(path or "argc")
    if base.endswith('.sh'):
        base = base[:-3]
    return base


def strip_comment(line: str) -> Optional[str]:
    m = re.match(r'\s*#(.*)$', line)
    if not m: return None
    s = m.group(1)
    if s.startswith(' '): s = s[1:]
    return s.rstrip('\n')


def parse_tags(block: List[str]) -> List[Tag]:
    tags: List[Tag] = []
    cur: Optional[Tag] = None
    for c in block:
        m = re.match(r'@([A-Za-z0-9_-]+)\b\s*(.*)$', c)
        if m:
            cur = Tag(m.group(1), m.group(2).rstrip())
            tags.append(cur)
        elif cur is not None:
            cur.cont.append(c.rstrip())
    return tags


def split_tag_text(text: str) -> List[str]:
    try:
        return shlex.split(text, posix=True)
    except Exception:
        return text.split()


def sanitize_id(name: str) -> str:
    s = name
    s = re.sub(r'^[+-]+', '', s)
    s = s.replace('-', '_').replace('.', '_').replace(':','_')
    s = re.sub(r'[^A-Za-z0-9_]', '_', s)
    return s.lower()


def opt_base(tok: str) -> Tuple[str, Dict[str,Any]]:
    info = dict(required=False, multi=False, delim=None, term=False, default=None,
                choice=None, choice_fn=None, skip=False, assigned=False, pref=False)
    # assigned marker --foo:[..]
    if ':' in tok and not tok.startswith('::'):
        left, right = tok.split(':',1)
        if right.startswith('['):
            tok = left + right
            info['assigned'] = True
    if tok.endswith('~'):
        info['term'] = True; tok = tok[:-1]
    if '[' in tok and tok.endswith(']'):
        pre, br = tok.split('[',1)
        body = br[:-1]
        tok = pre
        if body.startswith('?'):
            info['skip'] = True; body = body[1:]
        if body.startswith('='):
            vals = body[1:].split('|') if body[1:] else []
            info['choice'] = vals; info['default'] = vals[0] if vals else ''
        elif body.startswith('`') and body.endswith('`'):
            info['choice_fn'] = body[1:-1]
        else:
            info['choice'] = body.split('|') if body else []
    if tok.endswith(','):
        info['delim'] = ','; tok = tok[:-1]
    if tok.endswith('!'):
        info['required'] = True; tok = tok[:-1]
    elif tok.endswith('+'):
        info['required'] = True; info['multi'] = True; tok = tok[:-1]
    elif tok.endswith('*'):
        info['multi'] = True; tok = tok[:-1]
    if tok.endswith(','):
        info['delim'] = ','; tok = tok[:-1]
    if '=' in tok and not tok.startswith('='):
        left, val = tok.split('=',1)
        tok = left
        if val.startswith('`') and val.endswith('`'):
            info['default_fn'] = val[1:-1]
        else:
            info['default'] = val
    if tok.endswith('-*'):
        info['pref'] = True
    return tok, info


def parse_notation_token(t: str) -> str:
    return t.strip('<>')


def merge_info(p: Param, info: Dict[str,Any]):
    p.required = p.required or info.get('required', False)
    p.multiple_occurs = p.multiple_occurs or info.get('multi', False)
    if info.get('delim'): p.delimiter = info['delim']
    p.terminated = p.terminated or info.get('term', False)
    p.assigned = p.assigned or info.get('assigned', False)
    p.prefixed = p.prefixed or info.get('pref', False)
    if info.get('default') is not None: p.default = info.get('default')
    if info.get('default_fn'): p.default_fn = info.get('default_fn')
    if info.get('choice') is not None: p.choice = info.get('choice')
    if info.get('choice_fn'): p.choice_fn = info.get('choice_fn')
    p.skip_check = p.skip_check or info.get('skip', False)


def parse_option(tag: Tag, flag: bool) -> Param:
    toks = split_tag_text(tag.text)
    p = Param(kind='option', flag=flag, describe='', long_desc=tag.cont[:])
    desc_start = len(toks)
    option_seen = False
    for i,t in enumerate(toks):
        if t.startswith('$'):
            p.env = t; continue
        if t.startswith('<') and t.endswith('>'):
            p.notations.append(parse_notation_token(t)); continue
        if (t.startswith('-') or t.startswith('+')) and t not in ('-', '+'):
            base, info = opt_base(t)
            merge_info(p, info)
            p.names.append(base)
            option_seen = True
            # classify short/long
            if base.startswith('--') or (base.startswith('-') and len(base) > 2) or (base.startswith('+') and len(base) > 2):
                if p.long_name is None: p.long_name = base
            elif base.startswith('-') or base.startswith('+'):
                if p.short_name is None: p.short_name = base
            continue
        desc_start = i; break
    if desc_start < len(toks):
        p.describe = ' '.join(toks[desc_start:])
    if not p.describe:
        # find original after consumed tokens crudely: no desc
        p.describe = ''
    # choose id from long preferred, else short
    name_for_id = p.long_name or p.short_name or (p.names[0] if p.names else '')
    plus = name_for_id.startswith('+')
    p.id = ("plus_" if plus else "") + sanitize_id(name_for_id)
    # notation default
    if not flag:
        if not p.notations:
            n = p.id[5:] if p.id.startswith('plus_') else p.id
            p.notations = [n.upper()]
        # determine num args
        minv = len(p.notations); maxv: Optional[int] = len(p.notations)
        if p.notations:
            last = p.notations[-1]
            if last.endswith('*'):
                minv = len(p.notations)-1; maxv = None; p.multiple_values = True
            elif last.endswith('+'):
                minv = len(p.notations); maxv = None; p.multiple_values = True
            elif last.endswith('?'):
                minv = len(p.notations)-1; maxv = len(p.notations); p.multiple_values = True
        if p.terminated:
            minv = 1; maxv = None; p.multiple_values = True
        p.num_args = (minv, maxv)
    else:
        p.num_args = (0,0)
    p.raw_display = (p.long_name or p.short_name or '')
    return p


def parse_arg(tag: Tag) -> Optional[Param]:
    toks = split_tag_text(tag.text)
    if not toks: return None
    raw = toks[0]
    env = None; notation = None; desc_tokens = []
    for t in toks[1:]:
        if t.startswith('$') and env is None: env = t
        elif t.startswith('<') and t.endswith('>') and notation is None: notation = parse_notation_token(t)
        else: desc_tokens.append(t)
    p = Param(kind='arg', describe=' '.join(desc_tokens), long_desc=tag.cont[:], env=env)
    s = raw
    if s.endswith('...'):
        p.multiple = True; s = s[:-3]
    if '[' in s and s.endswith(']'):
        pre, br = s.split('[',1); body = br[:-1]; s = pre
        if body.startswith('?'):
            p.skip_check=True; body=body[1:]
        if body.startswith('='):
            vals = body[1:].split('|') if body[1:] else []
            p.choice = vals; p.default = vals[0] if vals else ''
        elif body.startswith('`') and body.endswith('`'):
            p.choice_fn = body[1:-1]
        else:
            p.choice = body.split('|') if body else []
    if s.endswith(','):
        p.delimiter=','; s=s[:-1]
    if s.endswith('!'):
        p.required=True; s=s[:-1]
    elif s.endswith('+'):
        p.required=True; p.multiple=True; s=s[:-1]
    elif s.endswith('*'):
        p.multiple=True; s=s[:-1]
    elif s.endswith('~'):
        p.multiple=True; p.terminated=True; s=s[:-1]
    if s.endswith(','):
        p.delimiter=','; s=s[:-1]
    if '=' in s:
        left,val=s.split('=',1); s=left
        if val.startswith('`') and val.endswith('`'): p.default_fn=val[1:-1]
        else: p.default=val
    p.id = sanitize_id(s)
    p.notation = notation or sanitize_id(s).upper()
    return p


def parse_env(tag: Tag) -> Optional[EnvDef]:
    toks = split_tag_text(tag.text)
    if not toks: return None
    raw=toks[0]; desc=' '.join(toks[1:])
    e=EnvDef(id='', describe=desc)
    s=raw
    if '[' in s and s.endswith(']'):
        pre, br=s.split('[',1); body=br[:-1]; s=pre
        if body.startswith('='):
            vals=body[1:].split('|'); e.choice=vals; e.default=vals[0] if vals else ''
        elif body.startswith('`') and body.endswith('`'):
            e.choice_fn=body[1:-1]
        else: e.choice=body.split('|') if body else []
    if s.endswith('!'):
        e.required=True; s=s[:-1]
    if '=' in s:
        left,val=s.split('=',1); s=left
        if val.startswith('`') and val.endswith('`'): e.default_fn=val[1:-1]
        else: e.default=val
    e.id=s
    return e


def apply_tags(node: Node, tags: List[Tag], is_cmd=False):
    for t in tags:
        if t.name == 'describe':
            node.describe=t.text; node.long_desc=t.cont[:]
        elif t.name == 'cmd':
            node.describe=t.text; node.long_desc=t.cont[:]
        elif t.name == 'alias':
            for a in t.text.split():
                if a and a not in node.aliases: node.aliases.append(a)
        elif t.name == 'arg':
            p=parse_arg(t)
            if p: node.args.append(p)
        elif t.name == 'option':
            node.options.append(parse_option(t, False))
        elif t.name == 'flag':
            node.options.append(parse_option(t, True))
        elif t.name == 'env':
            e=parse_env(t)
            if e: node.envs.append(e)
        elif t.name == 'meta':
            words=t.text.split(None,1)
            key=words[0] if words else ''
            val=words[1] if len(words)>1 else True
            if key == 'require-tools' and isinstance(val,str):
                node.meta.setdefault('require-tools',[]).extend([x for x in re.split(r'[,\s]+', val) if x])
            elif key == 'symbol' and isinstance(val,str):
                node.meta.setdefault('symbols',[]).append(val)
            else:
                node.meta[key]=val


def add_child(parent: Node, child: Node):
    parent.children[child.name]=child; child.parent=parent
    aliases=[]
    if '_' in child.name:
        aliases.append(child.name.replace('_','-'))
    aliases += child.aliases
    child.aliases=[]
    for a in aliases:
        if a not in child.aliases: child.aliases.append(a)
        parent.child_aliases[a]=child.name


def parse_script(path: str) -> Node:
    root=Node(script_name(path))
    try:
        text=open(path, encoding='utf-8').read().splitlines()
    except Exception:
        return root
    block: List[str]=[]
    def apply_root_block(b):
        tags=parse_tags(b)
        if tags and not any(t.name=='cmd' for t in tags):
            apply_tags(root,tags)
    for line in text:
        c=strip_comment(line)
        if c is not None:
            block.append(c); continue
        fm=re.match(r'\s*(?:function\s+)?([A-Za-z0-9_:+.\-]+)\s*\(\)\s*\{', line)
        if fm:
            fn=fm.group(1)
            tags=parse_tags(block)
            cmd_indices=[i for i,t in enumerate(tags) if t.name=='cmd']
            if cmd_indices:
                idx=cmd_indices[0]
                if idx>0: apply_tags(root,tags[:idx])
                parts=fn.split('::')
                parent=root
                for part in parts[:-1]:
                    name=part
                    if name not in parent.children:
                        add_child(parent, Node(name, fn='::'.join(parts[:parts.index(part)+1])))
                    parent=parent.children[name]
                child=Node(parts[-1], fn=fn)
                apply_tags(child,tags[idx:])
                add_child(parent,child)
            else:
                if fn == 'main':
                    apply_tags(root,tags); root.fn='main'
                else:
                    apply_root_block(block)
            block=[]; continue
        if re.search(r'eval\s+"?\$\([^)]*argc\s+--argc-eval', line):
            apply_root_block(block); block=[]; continue
        if line.strip()=="":
            apply_root_block(block); block=[]; continue
        # any other code ends a pending root-only block
        apply_root_block(block); block=[]
    apply_root_block(block)
    # inherit root options/envs into descendants
    if root.meta.get('inherit-flag-options'):
        def inh(n: Node):
            for ch in n.children.values():
                copied=[]
                for op in root.options:
                    q=Param(**op.__dict__); q.inherited=True; copied.append(q)
                ch.options = copied + ch.options
                inh(ch)
        inh(root)
    return root


def find_func_outputs(path: str, fn: str) -> List[str]:
    try: lines=open(path, encoding='utf-8').read().splitlines()
    except Exception: return []
    out=[]; in_fn=False; depth=0; heredoc=None
    for line in lines:
        if not in_fn:
            if re.match(r'\s*(?:function\s+)?'+re.escape(fn)+r'\s*\(\)\s*\{', line):
                in_fn=True; depth=line.count('{')-line.count('}')
            continue
        else:
            if heredoc:
                if line.strip()==heredoc:
                    heredoc=None
                else:
                    out.append(line.strip('\t'))
                continue
            m=re.search(r'cat\s+<<-?\'?(\w+)\'?', line)
            if m:
                heredoc=m.group(1); continue
            m=re.match(r'\s*echo\s+(["\']?)(.*)\1\s*$', line)
            if m:
                val=m.group(2)
                if not any(x in val for x in ['$','`']): out.append(val)
            depth += line.count('{')-line.count('}')
            if depth<=0: break
    return [x for x in out if x!='']


def choices_for(path: str, p) -> Optional[List[str]]:
    if getattr(p,'choice',None) is not None: return p.choice
    if getattr(p,'choice_fn',None): return find_func_outputs(path, p.choice_fn)
    return None


def default_for(p: Param, path: str) -> Optional[str]:
    if p.default is not None: return p.default
    if p.default_fn:
        vals=find_func_outputs(path,p.default_fn)
        return vals[0] if vals else ''
    return None


def q(s: str) -> str:
    return shlex.quote(str(s))


def arr_assign(name: str, vals: List[str]) -> str:
    return f"{name}=( " + ' '.join(q(v) for v in vals) + " )"


def scalar_assign(name: str, val: str) -> str:
    return f"{name}={q(val)}"


def heredoc_exit(msg: str, code: int) -> str:
    return "command cat >&2 <<-'EOF' \n" + msg.rstrip('\n') + "\nEOF\nexit " + str(code) + "\n"


def format_arg_usage(a: Param) -> str:
    n=a.notation or a.id.upper()
    if a.multiple:
        if a.required: return f"<{n}>..."
        return f"[{n}]..."
    if a.required: return f"<{n}>"
    return f"[{n}]"


def option_primary(op: Param) -> str:
    return op.long_name or op.short_name or (op.names[0] if op.names else '')


def format_opt_usage(op: Param) -> str:
    name=option_primary(op)
    if op.flag:
        return name + ('...' if op.multiple_occurs else '')
    notation = ' '.join(f"<{n}>" for n in op.notations)
    if op.terminated:
        notation=f"<{(op.id[5:] if op.id.startswith('plus_') else op.id).upper()}~>"
    elif op.multiple_occurs:
        notation=f"[{op.notations[0]}]..." if op.notations else f"[{op.id.upper()}]..."
    if op.assigned:
        return f"{name}=<{(op.id[5:] if op.id.startswith('plus_') else op.id).upper()}>"
    return (name + (" " + notation if notation else '')).strip()


def display_option_names(op: Param) -> str:
    parts=[]
    if op.short_name: parts.append(op.short_name)
    if op.long_name: parts.append(op.long_name)
    if not parts and op.names: parts.append(op.names[0])
    base=', '.join(parts)
    if op.flag:
        if op.multiple_occurs: base += '...'
        return base
    usage=format_opt_usage(op)
    if len(parts)>=2:
        # append value only to long half
        val=usage[len(op.long_name or option_primary(op)):]
        return f"{op.short_name}, {op.long_name}{val}"
    return usage


def node_path(node: Node) -> List[str]:
    xs=[]; n=node
    while n and n.parent:
        xs.append(n.name); n=n.parent
    return list(reversed(xs))


def command_lookup(parent: Node, tok: str) -> Optional[Node]:
    if tok in parent.children: return parent.children[tok]
    if tok in parent.child_aliases: return parent.children[parent.child_aliases[tok]]
    return None


def resolve(root: Node, args: List[str]) -> Tuple[Node,List[str],List[str],bool,Optional[str]]:
    # returns node, parse_args, command tokens consumed, is_help, error
    if root.children:
        # help/version at root before command
        if any(a in ('--help','-h','-help') for a in args):
            # if command before help, descend below
            pass
        # find first command-like token
        pre=[]; i=0
        node=root; consumed=[]
        # default subcommand
        default_child=None
        for ch in root.children.values():
            if ch.meta.get('default-subcommand'):
                default_child=ch
        # skip symbol tokens and root option tokens crudely
        while i < len(args):
            ch=command_lookup(node,args[i])
            if ch: break
            # default if a non-option and no command match
            if not args[i].startswith('-') and not args[i].startswith('+'):
                break
            pre.append(args[i]); i+=1
        if i < len(args) and command_lookup(node,args[i]):
            while i < len(args):
                ch=command_lookup(node,args[i])
                if not ch: break
                node=ch; consumed.append(args[i]); i+=1
            parse_args=pre+args[i:]
        elif default_child is not None:
            node=default_child; parse_args=args[:]
        else:
            # root help/version or error
            if any(a in ('--help','-h','-help') for a in args) or not args:
                return root,args,[],True,None
            bad=next((a for a in args if not a.startswith('-') and not a.startswith('+')), args[0])
            subs=[]
            for ch in root.children.values():
                subs.append(ch.name); subs.extend(ch.aliases)
            return root,args,[],False,f"error: `{root.name}` requires a subcommand but '{bad}' is not one of them\n  [subcommands: {', '.join(subs)}]"
        # descend nested command after pre? parse_args begins after consumed path
        if node.children:
            if any(a in ('--help','-h','-help') for a in parse_args):
                return node,parse_args,consumed,True,None
            if not parse_args or not command_lookup(node, parse_args[0]):
                subs=[]
                for ch in node.children.values(): subs.append(ch.name); subs.extend(ch.aliases)
                bad=parse_args[0] if parse_args else ''
                if bad:
                    return node,parse_args,consumed,False,f"error: `{root.name} {' '.join(node_path(node))}` requires a subcommand but '{bad}' is not one of them\n  [subcommands: {', '.join(subs)}]"
                return node,parse_args,consumed,False,f"error: `{root.name} {' '.join(node_path(node))}` requires a subcommand\n  [subcommands: {', '.join(subs)}]"
        return node,parse_args,consumed, any(a in ('--help','-h','-help') for a in parse_args), None
    else:
        return root,args,[], any(a in ('--help','-h','-help') for a in args), None


def option_maps(options: List[Param]):
    mp={}
    for op in options:
        for n in op.names:
            mp[n]=op
    return mp


def is_option_like(a: str) -> bool:
    return (a.startswith('-') and a!='-') or (a.startswith('+') and a!='+')


def split_delim(vals: List[str], delim: Optional[str]) -> List[str]:
    if delim == ',':
        out=[]
        for v in vals:
            out += ([] if v=='' else v.split(','))
        return out
    return vals


def validate_choice(path: str, p: Param, val: str, label: str) -> Optional[str]:
    if p.skip_check: return None
    ch=choices_for(path,p)
    if ch is not None and val not in ch:
        return f"error: invalid value `{val}` for `{label}`\n  [possible values: {', '.join(ch)}]"
    return None


def parse_values(root: Node, node: Node, parse_args: List[str], full_args: List[str], path: str) -> Tuple[Optional[str],Dict[str,Any],List[str]]:
    options=node.options[:]
    # ignore symbol pseudo args anywhere
    sym_prefixes=[]
    for spec in root.meta.get('symbols',[]):
        b,_=opt_base(spec.split()[0])
        if b.startswith('+'): sym_prefixes.append('+')
    args=[a for a in parse_args if not (a.startswith('+') and root.meta.get('symbols'))]
    mp=option_maps(options)
    vals: Dict[str,Any]={}
    positionals=[]; seen_counts={}
    i=0
    combine = bool(root.meta.get('combine-shorts') or node.meta.get('combine-shorts'))
    while i < len(args):
        a=args[i]
        if a == '--':
            positionals += args[i+1:]; break
        # help/version ignored in normal parse
        if a in ('--help','-h','-help','--version','-V'):
            i+=1; continue
        # combine short flags
        if combine and re.match(r'^-[A-Za-z]{2,}$', a) and a not in mp:
            ok=True
            for c in a[1:]:
                op=mp.get('-'+c)
                if not op or not op.flag: ok=False; break
            if ok:
                for c in a[1:]:
                    op=mp['-'+c]; vals[op.id]=int(vals.get(op.id,0))+1
                i+=1; continue
        op=None; inline_val=None; used_name=a
        if '=' in a:
            nm,iv=a.split('=',1)
            if nm in mp:
                op=mp[nm]; inline_val=iv; used_name=nm
        if op is None and a in mp:
            op=mp[a]; used_name=a
        # assigned only demands inline =
        if op is not None:
            if op.flag:
                if op.id in seen_counts and not op.multiple_occurs:
                    return f"error: the argument `{used_name}` cannot be used multiple times",{},[]
                seen_counts[op.id]=seen_counts.get(op.id,0)+1
                vals[op.id]=int(vals.get(op.id,0))+1
                i+=1; continue
            if op.assigned and inline_val is None:
                return f"error: incorrect number of values for `{used_name}=<{op.id.upper()}>`",{},[]
            if op.id in seen_counts and not op.multiple_occurs:
                return f"error: the argument `{used_name}` cannot be used multiple times",{},[]
            minc,maxc=op.num_args
            got=[]
            if inline_val is not None:
                got=[inline_val]
            else:
                j=i+1
                if op.terminated:
                    got=args[j:]; j=len(args)
                elif maxc is None:
                    while j < len(args) and args[j] != '--' and args[j] not in mp and not (('=' in args[j]) and args[j].split('=',1)[0] in mp):
                        if is_option_like(args[j]) and len(got) >= minc: break
                        got.append(args[j]); j+=1
                else:
                    while j < len(args) and len(got)<maxc:
                        if args[j] == '--' or args[j] in mp or (('=' in args[j]) and args[j].split('=',1)[0] in mp): break
                        if is_option_like(args[j]) and len(got) < minc: break
                        got.append(args[j]); j+=1
                i=j
            if len(got) < minc or (maxc is not None and len(got)>maxc):
                return f"error: incorrect number of values for `{used_name} {' '.join('<'+n+'>' for n in op.notations)}`".rstrip(),{},[]
            got=split_delim(got,op.delimiter)
            label=f"<{op.notations[0].rstrip('*+?') if op.notations else op.id.upper()}>"
            for gv in got:
                er=validate_choice(path,op,gv,label)
                if er: return er,{},[]
            seen_counts[op.id]=seen_counts.get(op.id,0)+1
            if op.multiple_occurs or op.multiple_values or len(got)!=1:
                vals.setdefault(op.id,[])
                vals[op.id].extend(got)
            else:
                vals[op.id]=got[0] if got else ''
            if inline_val is not None: i+=1
            continue
        if is_option_like(a):
            return f"error: unexpected argument `{a}` found",{},[]
        positionals.append(a); i+=1
    # defaults/env for options
    missing=[]
    for op in options:
        envnames=[]
        if op.env:
            if op.env == '$$':
                base=op.id[5:] if op.id.startswith('plus_') else op.id
                envnames += ['argc_'+base, base.upper()]
            else: envnames.append(op.env[1:])
        found_env=None
        for en in envnames:
            if en in os.environ:
                found_env=os.environ[en]; break
        if op.id not in vals and found_env is not None:
            vals[op.id]=found_env
        if op.id not in vals:
            d=default_for(op,path)
            if d is not None: vals[op.id]=d
        if op.required and op.id not in vals:
            missing.append(format_opt_usage(op))
    if missing:
        return "error: the following required arguments were not provided:\n" + '\n'.join('  '+m for m in missing),{},[]
    # assign positionals
    assigned_pos=[]; out_pos=[]
    if not node.args:
        out_pos=positionals[:]
    else:
        idx=0; missing_args=[]
        for ai,a in enumerate(node.args):
            remaining_defs=node.args[ai+1:]
            reserve=0
            for rd in remaining_defs:
                if rd.required: reserve += 1
                elif idx+reserve < len(positionals): reserve += 1
            vals_for=[]
            if a.multiple:
                take=max(0, len(positionals)-idx-reserve)
                if a.required and take<1: take=0
                vals_for=positionals[idx:idx+take]; idx+=take
                vals_for=split_delim(vals_for,a.delimiter)
                if a.required and not vals_for: missing_args.append(format_arg_usage(a))
            else:
                if idx < len(positionals): vals_for=[positionals[idx]]; idx+=1
                else:
                    # env/default
                    d=None
                    if a.env and a.env != '$$' and a.env[1:] in os.environ: d=os.environ[a.env[1:]]
                    if d is None: d=default_for(a,path)
                    if d is not None: vals_for=[d]
                    elif a.required: missing_args.append(format_arg_usage(a))
            # $$ env binding sets variable only
            if not vals_for and a.env == '$$':
                for en in ('argc_'+a.id, a.id.upper()):
                    if en in os.environ: vals[a.id]=os.environ[en]
            if vals_for:
                label=format_arg_usage(a)
                for v in vals_for:
                    er=validate_choice(path,a,v,label)
                    if er: return er,{},[]
                if a.multiple: vals[a.id]=vals_for[:]
                else: vals[a.id]=vals_for[0]
                assigned_pos += vals_for
        if missing_args:
            return "error: the following required arguments were not provided:\n" + '\n'.join('  '+m for m in missing_args),{},[]
        if idx < len(positionals):
            return f"error: unexpected argument `{positionals[idx]}` found",{},[]
        out_pos=assigned_pos
    vals['_positionals']=out_pos
    return None, vals, out_pos


def env_error_and_assigns(root: Node, node: Node, path: str) -> Tuple[Optional[str], List[str]]:
    envdefs=[]; seen=set()
    for e in root.envs + ([] if node is root else node.envs):
        if e.id in seen: continue
        seen.add(e.id); envdefs.append(e)
    # dotenv
    env=os.environ.copy(); assigns=[]
    if root.meta.get('dotenv') and os.path.exists('.env'):
        for line in open('.env', encoding='utf-8'):
            line=line.strip()
            if not line or line.startswith('#') or '=' not in line: continue
            k,v=line.split('=',1); v=v.strip().strip('"').strip("'")
            if k not in env:
                env[k]=v; assigns.append(f"export {k}={q(v)}")
    missing=[]
    for e in envdefs:
        val=env.get(e.id)
        if val is None:
            if e.default is not None: val=e.default
            elif e.default_fn:
                outs=find_func_outputs(path,e.default_fn); val=outs[0] if outs else ''
            if val is not None:
                assigns.append(f"export {e.id}={q(val)}")
                env[e.id]=val
        if val is None and e.required: missing.append(e.id)
        ch=e.choice if e.choice is not None else (find_func_outputs(path,e.choice_fn) if e.choice_fn else None)
        if val is not None and ch is not None and val not in ch:
            return f"error: invalid value `{val}` for environment variable `{e.id}`\n  [possible values: {', '.join(ch)}]", []
    if missing:
        return "error: the following required environments were not provided:\n" + '\n'.join('  '+m for m in missing), []
    return None, assigns


def help_text(root: Node, node: Node) -> str:
    parts=[]
    if node.describe:
        parts.append(node.describe)
        if node.long_desc:
            parts.append('\n'.join(node.long_desc).rstrip())
    path=node_path(node)
    usage=[root.name]+path
    if node.options: usage.append('[OPTIONS]')
    if node.children: usage.append('<COMMAND>')
    elif not node.args and node is root and root.children: usage.append('<COMMAND>')
    for a in node.args: usage.append(format_arg_usage(a))
    if not node.args and node.children and usage[-1] != '<COMMAND>': usage.append('<COMMAND>')
    parts.append('USAGE: ' + ' '.join(usage))
    if node.args:
        lines=['ARGS:']
        names=[format_arg_usage(a) for a in node.args]
        w=max(len(x) for x in names)
        for nm,a in zip(names,node.args):
            desc=a.describe
            if desc: lines.append(f"  {nm.ljust(w)}  {desc}")
            else: lines.append(f"  {nm}")
            for ld in a.long_desc:
                if ld!='': lines.append(' '*(w+4)+ld)
        parts.append('\n'.join(lines))
    opts=node.options[:]
    # add help/version pseudo
    if node is root:
        opts2=opts+[Param(kind='option',id='help',names=['-h','--help'],short_name='-h',long_name='--help',flag=True,describe='Print help'), Param(kind='option',id='version',names=['-V','--version'],short_name='-V',long_name='--version',flag=True,describe='Print version')]
    else:
        opts2=opts+[Param(kind='option',id='help',names=['-h','--help'],short_name='-h',long_name='--help',flag=True,describe='Print help' if not any(o.inherited for o in opts) else '')]
    if opts2:
        rows=[]
        for op in opts2:
            nm=display_option_names(op)
            desc=op.describe
            ch=choices_for('',op) if False else op.choice
            if ch: desc=(desc+' ' if desc else '')+f"[possible values: {', '.join(ch)}]"
            d=op.default
            if d is not None: desc=(desc+' ' if desc else '')+f"[default: {d}]"
            rows.append((nm,desc,op.long_desc))
        w=max(len(r[0]) for r in rows)
        lines=['OPTIONS:']
        for nm,desc,lds in rows:
            if desc: lines.append(f"  {nm.rjust(w)}  {desc}")
            else: lines.append(f"  {nm.rjust(w)}")
            for ld in lds:
                if ld=='': lines.append('')
                else: lines.append(' '*(w+4)+ld)
        parts.append('\n'.join(lines))
    if node.children:
        rows=[]
        for ch in node.children.values():
            desc=ch.describe
            if ch.aliases:
                desc=(desc+' ' if desc else '')+f"[aliases: {', '.join(ch.aliases)}]"
            rows.append((ch.name,desc))
        w=max((len(x[0]) for x in rows), default=0)
        lines=['COMMANDS:']
        for nm,desc in rows:
            if desc: lines.append(f"  {nm.ljust(w)}  {desc}")
            else: lines.append(f"  {nm}")
        parts.append('\n'.join(lines))
    return '\n\n'.join([p for p in parts if p is not None]).rstrip()+"\n"


def version_text(root: Node) -> str:
    ver=root.meta.get('version') or '0.0.0'
    return f"{root.name} {ver}\n"


def generate_eval(script: str, argv: List[str]) -> str:
    if not script:
        return "echo 'Error: No script file provided'\nexit 1\n"
    root=parse_script(script)
    node, parse_args, consumed, ishelp, err = resolve(root, argv)
    if err: return heredoc_exit(err,1)
    if (('--version' in argv) or ('-V' in argv)) and node is root:
        return heredoc_exit(version_text(root).rstrip('\n'),0)
    if ishelp:
        return heredoc_exit(help_text(root,node).rstrip('\n'),0)
    # require tools
    req=[]
    cur=node
    req += root.meta.get('require-tools',[])
    if node is not root: req += node.meta.get('require-tools',[])
    missing=[x for x in req if shutil.which(x) is None]
    if missing: return heredoc_exit(f"error: missing tools: {', '.join(missing)}",1)
    er, env_assigns=env_error_and_assigns(root,node,script)
    if er: return heredoc_exit(er,1)
    er, vals, positionals = parse_values(root,node,parse_args,argv,script)
    if er: return heredoc_exit(er,1)
    stem=script_name(script)
    assigns=[]; assigns += env_assigns
    full=[stem]+argv
    assigns.append(arr_assign('argc__args', full))
    if node.fn: assigns.append(scalar_assign('argc__fn', node.fn))
    assigns.append(arr_assign('argc__positionals', positionals))
    for k in sorted([x for x in vals.keys() if not x.startswith('_')]):
        v=vals[k]
        name='argc_'+k
        if isinstance(v,list): assigns.append(arr_assign(name,v))
        else: assigns.append(scalar_assign(name,str(v)))
    plain='\n'.join(assigns)+'\n'
    b64=base64.b64encode(plain.encode()).decode()
    out=[f"export ARGC_VARS={b64}"]+assigns
    if node.fn:
        call_args=' '.join(q(x) for x in positionals)
        out.append('if declare -F _argc_before >/dev/null; then _argc_before; fi')
        out.append(f"{node.fn}" + (" "+call_args if call_args else ""))
        out.append('if declare -F _argc_after >/dev/null; then _argc_after; fi')
    return '\n'.join(out)+'\n'


def to_json_node(root: Node, n: Node) -> Dict[str,Any]:
    def opj(o: Param):
        return dict(id=o.id,long_name=o.long_name,short_name=o.short_name,describe=o.describe,flag=o.flag,notations=o.notations,required=o.required,multiple_values=o.multiple_values,multiple_occurs=o.multiple_occurs,num_args=list(o.num_args),delimiter=o.delimiter,terminated=o.terminated,prefixed=o.prefixed,assigned=o.assigned,default=default_for(o,'') if o.default else o.default,choice=o.choice,env=o.env,inherited=o.inherited)
    return dict(name=n.name, describe=n.describe or None, version=n.meta.get('version'), aliases=n.aliases, flag_options=[opj(o) for o in n.options], positionals=[dict(id=a.id,describe=a.describe,notation=a.notation,required=a.required,multiple=a.multiple,delimiter=a.delimiter,terminated=a.terminated,default=a.default,choice=a.choice,env=a.env) for a in n.args], envs=[e.__dict__ for e in n.envs], subcommands=[to_json_node(root,c) for c in n.children.values()], command_fn=n.fn)


def compgen(shell: str, file: str, words: List[str]) -> str:
    if not file or not os.path.exists(file): return ''
    root=parse_script(file)
    # remove program word
    args=words[1:] if words else []
    # if completing option list
    node, parse_args, consumed, _, _ = resolve(root,args)
    cur=words[-1] if words else ''
    lines=[]
    if cur.startswith('-') or cur.startswith('+'):
        opts=node.options[:]
        opts.append(Param(kind='option',id='help',names=['--help','-h'],long_name='--help',short_name='-h',flag=True,describe='Print help'))
        if node is root: opts.append(Param(kind='option',id='version',names=['--version','-V'],long_name='--version',short_name='-V',flag=True,describe='Print version'))
        for o in opts:
            for nm in o.names:
                if len(nm)>2 or nm.startswith('--'):
                    desc=f" ({o.describe})" if o.describe else ' '
                    lines.append(nm+desc)
    else:
        for ch in node.children.values():
            desc=f" ({ch.describe})" if ch.describe else ' '
            lines.append(ch.name+desc)
    return '\n'.join(lines)+('\n' if lines else '')


def completions(shell: str, cmds: List[str]) -> str:
    if shell == 'bash':
        return """_argc_completer() {
    declare -a _argc_completer_words
    _argc_completer_parse_line
    while IFS=$'\n' read -r line; do
        COMPREPLY+=( "$line" )
    done < <(argc --argc-compgen bash "" "${_argc_completer_words[@]}" 2>/dev/null)
}
_argc_completer_parse_line() {
    _argc_completer_words=( $COMP_LINE )
}
complete -F _argc_completer -o nospace -o nosort \
    argc %s
""" % (' '.join(cmds))
    return f"# completion for {shell}\n"


def run_parallel(args: List[str]) -> int:
    if len(args)<2:
        print('Usage: argc --argc-parallel <SCRIPT> <ARGS>...', file=sys.stderr); return 1
    script=args[0]; groups=[]; cur=[]
    for a in args[1:]:
        if a == ':::':
            if cur: groups.append(cur); cur=[]
        else: cur.append(a)
    if cur: groups.append(cur)
    try: content=open(script,encoding='utf-8').read().splitlines()
    except Exception as e:
        print(e,file=sys.stderr); return 1
    pre=[]
    for line in content:
        if 'argc --argc-eval' in line: break
        pre.append(line)
    assigns=base64.b64decode(os.environ.get('ARGC_VARS','').encode()).decode() if os.environ.get('ARGC_VARS') else ''
    procs=[]
    for g in groups:
        fn=g[0]; fargs=g[1:]
        code='\n'.join(pre)+'\n'+assigns+'\n'+fn+' '+ ' '.join(q(x) for x in fargs)+'\n'
        procs.append(subprocess.Popen(['/usr/bin/bash','-c',code], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True))
    outs=[]
    code=0
    for p in procs:
        o,e=p.communicate(); outs.append((o,e)); code=max(code,p.returncode)
    for o,e in outs:
        if o: sys.stdout.write(o)
    for o,e in outs:
        if e: sys.stderr.write(e)
    return code


def create_argcfile(recipes: List[str]) -> int:
    if os.path.exists('Argcfile.sh'):
        print('Argcfile.sh already exists.', file=sys.stderr); return 1
    with open('Argcfile.sh','w') as f:
        f.write('#!/usr/bin/env bash\n\nset -e\n\n')
        for r in recipes:
            f.write(f"# @cmd\n{r}() {{\n    echo TODO {r}\n}}\n\n")
        f.write('# See more details at https://github.com/sigoden/argc\neval "$(argc --argc-eval "$0" "$@")"\n')
    os.chmod('Argcfile.sh',0o755)
    print('Argcfile.sh has been successfully created.')
    return 0


def mangen(file: str, outdir: str) -> int:
    root=parse_script(file); os.makedirs(outdir,exist_ok=True)
    def man_for(n: Node, name_parts: List[str]):
        fname='-'.join([root.name]+name_parts)
        path=os.path.join(outdir,fname+'.1')
        synopsis=' '.join([root.name]+name_parts+(['[OPTIONS]'] if n.options else [])+([format_arg_usage(a) for a in n.args] or (['<COMMAND>'] if n.children else [])))
        with open(path,'w') as f:
            f.write(f".TH {fname.upper()} 1  \"{fname} {n.meta.get('version','0.0.0')}\" \n")
            f.write(f".SH NAME\n{fname.replace('-', '\\-')} \\- {n.describe}\n")
            f.write(f".SH SYNOPSIS\n\\fB{root.name+' '+ ' '.join(name_parts) if name_parts else root.name}\\fR {' '.join(synopsis.split()[len(name_parts)+1:])}\n")
        print('saved '+path)
        for ch in n.children.values(): man_for(ch,name_parts+[ch.name])
    man_for(root,[]); return 0


def main(argv: List[str]) -> int:
    if argv and argv[0].startswith('--argc-'):
        cmd=argv[0]; rest=argv[1:]
        if cmd=='--argc-help':
            print("A bash cli framework, also a bash-based command runner - https://github.com/sigoden/argc\n")
            print("USAGE:")
            print("    argc --argc-eval <FILE> <ARGS~>            Use `eval \"$(argc --argc-eval \"$0\" \"$@\")\"`")
            print("    argc --argc-create <RECIPES~>              Create a boilerplate argcfile")
            print("    argc --argc-run <FILE> <ARGS~>             Run an argc-based script")
            print("    argc --argc-build <FILE> <OUTPATH?>        Generate bashscript without argc dependency")
            print("    argc --argc-mangen <FILE> <OUTDIR>         Generate man pages")
            print("    argc --argc-completions <SHELL> <CMDS>     Generate shell completion scripts")
            print("    argc --argc-compgen <SHELL> <FILE> <ARGS>  Generate completion candidates")
            print("    argc --argc-export <FILE>                  Export command line definitions as json")
            print("    argc --argc-parallel <FILE> <ARGS~>        Run functions in parallel")
            print("    argc --argc-script-path                    Print current argcfile path")
            print("    argc --argc-shell-path                     Print current shell path")
            print("    argc --argc-help                           Print help information")
            print("    argc --argc-version                        Print version information\n")
            return 0
        if cmd=='--argc-version': print(f'argc {VERSION}'); return 0
        if cmd=='--argc-eval':
            script=rest[0] if rest else ''
            sys.stdout.write(generate_eval(script, rest[1:] if rest else [])); return 0
        if cmd=='--argc-export':
            if not rest: print('No script file provided', file=sys.stderr); return 1
            print(json.dumps(to_json_node(parse_script(rest[0]), parse_script(rest[0])), indent=2)); return 0
        if cmd=='--argc-compgen':
            if len(rest)>=2: sys.stdout.write(compgen(rest[0], rest[1], rest[2:])); return 0
            return 0
        if cmd=='--argc-completions':
            if not rest: print('Usage: argc --argc-completions <SHELL> [CMDS]...', file=sys.stderr); return 1
            sys.stdout.write(completions(rest[0], rest[1:])); return 0
        if cmd=='--argc-create': return create_argcfile(rest)
        if cmd=='--argc-run':
            if not rest: print('No script file provided', file=sys.stderr); return 1
            return subprocess.call(['/usr/bin/bash']+rest)
        if cmd=='--argc-script-path': print(os.path.join(os.getcwd(),'Argcfile.sh')); return 0
        if cmd=='--argc-shell-path': print('/usr/bin/bash'); return 0
        if cmd=='--argc-parallel': return run_parallel(rest)
        if cmd=='--argc-mangen':
            if not rest: print('No script file provided', file=sys.stderr); return 1
            return mangen(rest[0], rest[1] if len(rest)>1 else '.')
        if cmd=='--argc-build':
            if not rest: print('No script file provided', file=sys.stderr); return 1
            src=rest[0]; out=rest[1] if len(rest)>1 else src
            if os.path.isdir(out): out=os.path.join(out, os.path.basename(src))
            os.makedirs(os.path.dirname(out) or '.', exist_ok=True); shutil.copyfile(src,out); os.chmod(out,0o755); print('saved '+out); return 0
    # default argcfile runner
    path=os.path.join(os.getcwd(),'Argcfile.sh')
    if not os.path.exists(path):
        print('Argcfile not found, try `argc --argc-help` for help.', file=sys.stderr); return 1
    return subprocess.call(['/usr/bin/bash', path]+argv)

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
